  UEe = `Seterusnya`,
  WEe = `Sebelumnya`,
  GEe = `Input Steam`,
  KEe = `Untuk membolehkan anda bermain mana-mana permainan, walaupun jika ia tidak menyokong alat kawalan permainan, Deck anda menggunakan <2>Input Steam</2>, iaitu sistem yang menterjemahkan input fizikal anda menjadi arahan untuk permainan.`,
  qEe = `Konfigurasi alat kawalan untuk <1></1> anda menggunakan <2>Input Steam</2>, iaitu sistem yang menterjemahkan input fizikal anda menjadi arahan untuk permainan. Ini membolehkan anda bermain mana-mana permainan, walaupun jika ia tidak direka untuk alat kawalan tertentu anda atau tidak menyokong gamepad.`,
  JEe = `<1>Arahan</1> boleh menjadi mana-mana jenis input yang digunakan oleh permainan – butang B pada gamepad, kekunci Enter, klik butang kiri tetikus dan sebagainya.`,
  YEe = `Susun Atur Alat Kawalan setiap permainan mengandungi senarai semua bahagian fizikal alat kawalan anda serta arahan yang ditetapkan padanya.`,
  XEe = `Menyesuaikan adalah semudah memilih input fizikal dan arahan yang anda inginkan.`,
  ZEe = `Permainan Deck Verified sentiasa mempunyai Susun Atur Alat Kawalan yang berfungsi sepenuhnya, jadi anda boleh terus melancarkannya dan mula bermain.`,
  QEe = `Secara lalai, ia mungkin tidak menggunakan input fizikal tambahan yang dimiliki Deck berbanding gamepad biasa, tetapi bahagian <1>Tetapan Pantas</1> memudahkan anda untuk menetapkan arahan untuk input tersebut.`,
  $Ee = `Secara lalai, ia mungkin tidak menggunakan input fizikal tambahan yang dimiliki Deck berbanding gamepad biasa, tetapi bahagian <1>Tetapan Pantas</1> memudahkan anda untuk menetapkan arahan untuk input tersebut.`,
  eDe = `Arahan`,
  tDe = `Input Fizikal`,
