  VXe = `Butang Dayakan Giroskop – Tarik Penuh Pencetus Kanan`,
  HXe = `Input giroskop akan dihidupkan hanya apabila butang Pencetus Kanan ditekan.`,
  UXe = `Input giroskop akan dihidupkan hanya apabila Pencetus Kiri ditarik secara lembut.`,
  WXe = `Butang Dayakan Giroskop – Tarik Lembut Pencetus Kanan`,
  GXe = `Input giroskop akan dihidupkan hanya apabila Pencetus Kanan ditarik secara lembut.`,
  KXe = `Butang Dayakan Giroskop – A`,
  qXe = `Input giroskop akan dihidupkan hanya apabila butang A ditekan.`,
  JXe = `Butang Dayakan Giroskop – B`,
