  iQe = `Butang Dayakan Giroskop – Sentuhan Pad Kiri`,
  aQe = `Input giroskop akan dihidupkan hanya apabila Trackpad Kiri disentuh.`,
  oQe = `Butang Dayakan Giroskop – Sentuhan Pad Bersatu`,
  sQe = `Input giroskop akan dihidupkan apabila mana-mana bahagian Trackpad disentuh.`,
  cQe = `Butang Dayakan Giroskop – Klik Pad Kanan`,
