  bQe = `Input giroskop akan dihidupkan hanya apabila butang Pencetus Kanan ditekan.`,
  xQe = `Input giroskop akan dihidupkan hanya apabila Pencetus Kiri ditarik secara lembut.`,
  SQe = `Butang Dayakan Giroskop – Tarik Lembut Pencetus Kanan`,
  CQe = `Input giroskop akan dihidupkan hanya apabila Pencetus Kanan ditarik secara lembut.`,
  wQe = `Butang Dayakan Giroskop – A`,
  TQe = `Input giroskop akan dihidupkan hanya apabila butang A ditekan.`,
  EQe = `Butang Dayakan Giroskop – B`,
  DQe = `Input giroskop akan dihidupkan hanya apabila butang B ditekan.`,
  OQe = `Butang Dayakan Giroskop – X`,
